// One item per PR from "Split PRs", one status document per PR from "Head status" (same order).
const prs = $('Split PRs').all().map(i => i.json);
const stats = $input.all().map(i => i.json);
const now = Date.now(), STALE_H = 24;
const rows = prs.map((pr, i) => {
  const s = stats[i] || {};
  const ctx = (name) => (s.statuses || []).filter(x => x.context === name).sort((a,b) => (a.created_at < b.created_at ? 1 : -1))[0];
  const checks = ctx('checks / checks (pull_request)'), drift = ctx('checks-drift');
  const ageH = Math.round((now - Date.parse(pr.created_at)) / 36e5);
  const idleH = Math.round((now - Date.parse(pr.updated_at)) / 36e5);
  const flags = [];
  if (ageH >= STALE_H) flags.push(`open ${ageH} h`);
  if (!checks) flags.push('no checks status (rebase + push)');
  else if (checks.status !== 'success') flags.push(`checks ${checks.status}`);
  if (drift && drift.status === 'failure') flags.push('fails against current master');
  if (pr.draft) flags.push('draft');
  return { number: pr.number, title: pr.title, url: pr.html_url, author: pr.author, ageH, idleH, flags };
});
const flagged = rows.filter(r => r.flags.length);
if (!flagged.length) return [];
const lines = flagged.map(r => `• #${r.number} ${r.title} (${r.author}, ${r.ageH} h old, idle ${r.idleH} h): ${r.flags.join(', ')}`);
const body = `PR watch: ${flagged.length} of ${rows.length} open pull request(s) need a look\n` + lines.join('\n');
const html = `<b>PR watch:</b> ${flagged.length} of ${rows.length} open pull request(s) need a look<ul>` +
  flagged.map(r => `<li><a href="${r.url}">#${r.number}</a> ${r.title} <i>(${r.author}, ${r.ageH} h old, idle ${r.idleH} h)</i>: ${r.flags.join(', ')}</li>`).join('') + '</ul>';
return [{ json: { txn_id: `prwatch-${now}`, matrixPayload: { msgtype: 'm.notice', body, format: 'org.matrix.custom.html', formatted_body: html }, flagged: flagged.length, total: rows.length } }];

const prs = Array.isArray($input.first().json) ? $input.first().json : $input.all().map(i => i.json);
return prs.map(pr => ({ json: { number: pr.number, title: pr.title, sha: pr.head.sha, created_at: pr.created_at,
  updated_at: pr.updated_at, html_url: pr.html_url, author: (pr.user || {}).login, draft: !!pr.draft } }));
